        for f in "ABCDE"
        for c in ("observed", "latent", "ordinal_one")
    ]
    configurations += [
        (4, "B", "observed", name, cast(dict[str, object], options))
        for name, options in (
            ("c025", {"error_correlation": 0.25}),
